PRAGMA foreign_keys = OFF;

DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "model_type" varchar, "model_id" integer, "description" text, "ip_address" varchar, "user_agent" text, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS `addresses`;
CREATE TABLE "addresses" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar check ("type" in ('billing', 'shipping', 'commercial', 'residential')) not null default 'residential', "zipcode" varchar, "street" varchar not null, "number" varchar, "complement" varchar, "neighborhood" varchar, "city" varchar not null default 'Luanda', "state" varchar not null default 'Luanda', "country" varchar not null default 'Angola', "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);

DROP TABLE IF EXISTS `business_units`;
CREATE TABLE "business_units" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "logo" varchar, "phone" varchar, "email" varchar, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime);

DROP TABLE IF EXISTS `categories`;
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "business_unit_id" integer, "parent_id" integer, "name" varchar not null, "slug" varchar not null, "description" text, "type" varchar check ("type" in ('product', 'service', 'course')) not null default 'product', "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("business_unit_id") references "business_units"("id") on delete set null, foreign key("parent_id") references "categories"("id") on delete set null);

DROP TABLE IF EXISTS `complaints_reports`;
CREATE TABLE "complaints_reports" ("id" integer primary key autoincrement not null, "protocol" varchar not null, "type" varchar not null, "is_anonymous" tinyint(1) not null default '0', "business_unit" varchar, "category" varchar not null, "order_or_invoice_ref" varchar, "incident_date" date, "name" varchar, "email" varchar, "phone" varchar, "nif_or_company" varchar, "subject" varchar not null, "description" text not null, "attachment_id" integer, "attachment_name" varchar, "attachment_mime" varchar, "status" varchar not null default 'recebido', "response_notes" text, "responded_at" datetime, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS `course_enrollments`;
CREATE TABLE "course_enrollments" ("id" integer primary key autoincrement not null, "course_id" integer not null, "customer_id" integer not null, "order_id" integer, "status" varchar not null default 'pending', "enrolled_at" datetime not null default (CURRENT_TIMESTAMP), "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references orders("id") on delete set null on update no action, foreign key("customer_id") references customers("id") on delete cascade on update no action, foreign key("course_id") references courses("id") on delete cascade on update no action);

DROP TABLE IF EXISTS `course_lessons`;
CREATE TABLE "course_lessons" ("id" integer primary key autoincrement not null, "course_module_id" integer not null, "title" varchar not null, "description" text, "video_url" varchar, "content" text, "duration_minutes" integer not null default '0', "sort_order" integer not null default '0', "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("course_module_id") references "course_modules"("id") on delete cascade);

DROP TABLE IF EXISTS `course_modules`;
CREATE TABLE "course_modules" ("id" integer primary key autoincrement not null, "course_id" integer not null, "title" varchar not null, "description" text, "sort_order" integer not null default '0', "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);

DROP TABLE IF EXISTS `course_progress`;
CREATE TABLE "course_progress" ("id" integer primary key autoincrement not null, "enrollment_id" integer not null, "lesson_id" integer not null, "completed" tinyint(1) not null default '0', "completed_at" datetime, "last_position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("enrollment_id") references "course_enrollments"("id") on delete cascade, foreign key("lesson_id") references "course_lessons"("id") on delete cascade);

DROP TABLE IF EXISTS `courses`;
CREATE TABLE "courses" ("id" integer primary key autoincrement not null, "business_unit_id" integer not null, "category_id" integer, "name" varchar not null, "slug" varchar not null, "description" text, "short_description" varchar, "thumbnail" varchar, "price" numeric not null default '0', "duration_hours" integer not null default '0', "level" varchar check ("level" in ('beginner', 'intermediate', 'advanced')) not null default 'beginner', "status" varchar not null default 'draft', "published_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete set null);

DROP TABLE IF EXISTS `customers`;
CREATE TABLE "customers" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar check ("type" in ('individual', 'company')) not null default 'individual', "document" varchar, "company_name" varchar, "trade_name" varchar, "birth_date" date, "phone" varchar, "whatsapp" varchar, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);

DROP TABLE IF EXISTS `employees`;
CREATE TABLE "employees" ("id" integer primary key autoincrement not null, "user_id" integer not null, "employee_code" varchar not null, "position" varchar not null, "department" varchar not null, "business_unit_id" integer, "hire_date" date, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("business_unit_id") references "business_units"("id") on delete set null);

DROP TABLE IF EXISTS `files`;
CREATE TABLE "files" ("id" integer primary key autoincrement not null, "user_id" integer, "fileable_type" varchar not null, "fileable_id" integer not null, "name" varchar not null, "original_name" varchar not null, "path" varchar not null, "mime_type" varchar not null, "size" integer not null, "disk" varchar not null default 'public', "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS `messages`;
CREATE TABLE "messages" ("id" integer primary key autoincrement not null, "service_request_id" integer not null, "user_id" integer not null, "message" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("service_request_id") references "service_requests"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);

DROP TABLE IF EXISTS `migrations`;
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));

DROP TABLE IF EXISTS `order_items`;
CREATE TABLE "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer, "name" varchar not null, "sku" varchar, "quantity" integer not null default '1', "unit_price" numeric not null default '0', "total" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete set null);

DROP TABLE IF EXISTS `orders`;
CREATE TABLE "orders" ("id" integer primary key autoincrement not null, "number" varchar not null, "customer_id" integer not null, "business_unit_id" integer not null, "status" varchar not null default 'pending', "payment_status" varchar not null default 'pending', "subtotal" numeric not null default '0', "discount" numeric not null default '0', "shipping" numeric not null default '0', "total" numeric not null default '0', "shipping_address_id" integer, "billing_address_id" integer, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("shipping_address_id") references "addresses"("id") on delete set null, foreign key("billing_address_id") references "addresses"("id") on delete set null);

DROP TABLE IF EXISTS `payments`;
CREATE TABLE "payments" ("id" integer primary key autoincrement not null, "order_id" integer not null, "method" varchar check ("method" in ('pix', 'credit_card', 'debit_card', 'boleto', 'multicaixa', 'manual')) not null, "transaction_id" varchar, "amount" numeric not null default '0', "status" varchar not null default 'pending', "paid_at" datetime, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade);

DROP TABLE IF EXISTS `permissions`;
CREATE TABLE "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "group" varchar, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS `product_images`;
CREATE TABLE "product_images" ("id" integer primary key autoincrement not null, "product_id" integer not null, "path" varchar not null, "alt" varchar, "sort_order" integer not null default '0', "is_primary" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);

DROP TABLE IF EXISTS `products`;
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "business_unit_id" integer not null, "category_id" integer, "sku" varchar not null, "name" varchar not null, "slug" varchar not null, "description" text, "short_description" varchar, "price" numeric not null default '0', "cost_price" numeric, "stock_quantity" integer not null default '0', "minimum_stock" integer not null default '5', "weight" numeric, "status" varchar not null default 'active', "featured" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete set null);

DROP TABLE IF EXISTS `quote_items`;
CREATE TABLE "quote_items" ("id" integer primary key autoincrement not null, "quote_id" integer not null, "description" varchar not null, "quantity" integer not null default '1', "unit_price" numeric not null default '0', "total" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("quote_id") references "quotes"("id") on delete cascade);

DROP TABLE IF EXISTS `quotes`;
CREATE TABLE "quotes" ("id" integer primary key autoincrement not null, "number" varchar not null, "service_request_id" integer, "customer_id" integer not null, "business_unit_id" integer not null, "created_by" integer, "subtotal" numeric not null default '0', "discount" numeric not null default '0', "total" numeric not null default '0', "valid_until" date, "status" varchar check ("status" in ('draft', 'sent', 'viewed', 'approved', 'rejected', 'expired', 'cancelled')) not null default 'draft', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("service_request_id") references "service_requests"("id") on delete set null, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);

DROP TABLE IF EXISTS `reviews`;
CREATE TABLE "reviews" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "service_request_id" integer not null, "rating" integer not null, "comment" text, "status" varchar not null default 'approved', "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("service_request_id") references "service_requests"("id") on delete cascade);

DROP TABLE IF EXISTS `role_permissions`;
CREATE TABLE "role_permissions" ("id" integer primary key autoincrement not null, "role_id" integer not null, "permission_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("role_id") references "roles"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade);

DROP TABLE IF EXISTS `roles`;
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS `service_request_status_histories`;
CREATE TABLE "service_request_status_histories" ("id" integer primary key autoincrement not null, "service_request_id" integer not null, "user_id" integer, "old_status" varchar, "new_status" varchar not null, "comment" text, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("service_request_id") references "service_requests"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS `service_requests`;
CREATE TABLE "service_requests" ("id" integer primary key autoincrement not null, "protocol" varchar not null, "customer_id" integer not null, "business_unit_id" integer not null, "service_id" integer, "assigned_to" integer, "title" varchar not null, "description" text not null, "priority" varchar check ("priority" in ('low', 'normal', 'high', 'urgent')) not null default 'normal', "status" varchar check ("status" in ('new', 'in_analysis', 'waiting_customer', 'quoted', 'approved', 'in_progress', 'in_review', 'completed', 'cancelled')) not null default 'new', "requested_date" date, "estimated_date" date, "completed_at" datetime, "cancelled_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("customer_id") references "customers"("id") on delete cascade, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("service_id") references "services"("id") on delete set null, foreign key("assigned_to") references "employees"("id") on delete set null);

DROP TABLE IF EXISTS `services`;
CREATE TABLE "services" ("id" integer primary key autoincrement not null, "business_unit_id" integer not null, "category_id" integer, "name" varchar not null, "slug" varchar not null, "description" text, "short_description" varchar, "base_price" numeric, "pricing_type" varchar check ("pricing_type" in ('fixed', 'quote', 'custom')) not null default 'quote', "estimated_days" integer, "status" varchar not null default 'active', "featured" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("business_unit_id") references "business_units"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete set null);

DROP TABLE IF EXISTS `stock_movements`;
CREATE TABLE "stock_movements" ("id" integer primary key autoincrement not null, "product_id" integer not null, "user_id" integer, "type" varchar check ("type" in ('entry', 'exit', 'adjustment', 'return', 'sale')) not null, "quantity" integer not null, "previous_quantity" integer not null, "current_quantity" integer not null, "reason" varchar, "reference_type" varchar, "reference_id" integer, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("product_id") references "products"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS `users`;
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "phone" varchar, "avatar" varchar, "role_id" integer, "business_unit_id" integer, "status" varchar not null default 'active', "email_verified_at" datetime, "last_login_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("role_id") references "roles"("id") on delete set null, foreign key("business_unit_id") references "business_units"("id") on delete set null);

DROP TABLE IF EXISTS `worker_attachments`;
CREATE TABLE "worker_attachments" ("id" integer primary key autoincrement not null, "service_request_id" integer, "user_id" integer, "name" varchar, "mime_type" varchar, "content" blob, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS `worker_contacts`;
CREATE TABLE "worker_contacts" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "subject" varchar not null, "message" text not null, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS `worker_rate_limits`;
CREATE TABLE "worker_rate_limits" ("key" varchar not null, "attempts" integer not null default '0', "expires_at" datetime, primary key ("key"));

DROP TABLE IF EXISTS `worker_sessions`;
CREATE TABLE "worker_sessions" ("token_hash" varchar not null, "user_id" integer not null, "expires_at" datetime, "created_at" datetime, primary key ("token_hash"));

