INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('1', '3', '8', 'Gestão e Estruturação Prática de MPMEs em Angola', 'gestao-estruturacao-mpme', 'Curso completo e focado no mercado angolano. O programa aborda desde a organização societária e contábil até a digitalização das vendas e fidelização de clientes.', 'Aprenda a organizar processos administrativos, finanças básicas e conformidade tributária para crescer com solidez.', '/images/courses/gestao-estruturacao-mpme.jpg', '65000', '24', 'intermediate', 'published', '2026-09-21T13:51:35', '2026-09-21T13:51:35', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('2', '3', '9', 'Transformação Digital e Automação de Processos', 'transformacao-digital-para-empresas', 'Aprenda na prática a escolher os melhores sistemas de gestão, integrar WhatsApp Business e automatizar tarefas repetitivas.', 'Implemente ferramentas modernas, reduza retrabalho e aumente a produtividade da sua equipe.', '/images/courses/transformacao-digital-para-empresas.jpg', '45000', '16', 'beginner', 'published', '2026-09-21T13:51:35', '2026-09-21T13:51:35', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('3', '3', '9', 'Cibersegurança: Defesa, Segurança da Informação e Redes', 'ciberseguranca', 'A formação em Cibersegurança da RACHI Academy capacita profissionais e equipas para a identificação, prevenção e mitigação de ameaças cibernéticas. O programa combina fundamentos teóricos sólidos com práticas reais de hardening, conformidade com a Lei de Proteção de Dados (APD Angola), defesa em profundidade e resposta a incidentes críticos.', 'Formação prática para prevenir ameaças digitais, proteger dados e reforçar a segurança da informação institucional e pessoal.', '/images/courses/ciberseguranca.jpg', '85000', '60', 'intermediate', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('4', '3', '9', 'Competências Digitais e Produtividade Tecnológica', 'competencias-digitais', 'Desenvolva proficiência nas principais ferramentas do ambiente de trabalho contemporâneo. Desde a gestão colaborativa de documentos em nuvem até automações básicas de planilhas e comunicação eficiente para aumentar a produtividade profissional.', 'Capacitação completa no uso de ferramentas digitais, produtividade em nuvem e tecnologias essenciais ao dia a dia corporativo moderno.', '/images/courses/competencias-digitais.jpg', '45000', '40', 'beginner', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('5', '3', '8', 'Formação Corporativa & Capacitação In-Company', 'formacao-corporativa', 'Programa executivo desenhado especificamente para empresas que buscam elevar a maturidade operacional, digital e de liderança dos seus colaboradores com métricas tangíveis de desempenho e ROI educacional.', 'Formação à medida para equipas, departamentos e organizações, alinhada aos objectivos estratégicos e resultados do negócio.', '/images/courses/formacao-corporativa.jpg', '150000', '50', 'advanced', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('6', '3', '8', 'Formação Profissional & Aceleração de Empregabilidade', 'formacao-profissional', 'Voltado para jovens talentos e profissionais em transição, com ênfase em projetos reais, mentoria individual de carreira e desenvolvimento de competências comportamentais e técnicas essenciais.', 'Programas práticos de capacitação para desenvolver competências técnicas demandadas pelo mercado e acelerar sua inserção profissional.', '/images/courses/formacao-profissional.jpg', '50000', '48', 'beginner', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('7', '3', '8', 'Gestão Empresarial, Estratégia e Operações', 'gestao-empresarial', 'Domine a governança corporativa, planejamento estratégico, orçamentação e tomada de decisão fundamentada em dados. Ideal para gestores, administradores e empresários que desejam expandir com sustentabilidade.', 'Capacitação profunda em planeamento, organização, finanças, processos e operações para potencializar a gestão de empresas no mercado angolano.', '/images/courses/gestao-empresarial.jpg', '95000', '60', 'intermediate', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('8', '3', '8', 'Liderança Executiva, Gestão de Equipas e Comunicação', 'lideranca', 'A liderança de sucesso requer empatia, firmeza e visão de futuro. Esta formação instrumentaliza líderes para inspirar colaboradores, delegar com eficácia, gerir conflitos e conduzir transformações nas organizações.', 'Desenvolvimento de competências de liderança estratégica, inteligência emocional e condução de equipas rumo ao alto desempenho.', '/images/courses/lideranca.jpg', '75000', '40', 'advanced', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('9', '3', '9', 'Auditoria de Sistemas & Compliance em Segurança (APD)', 'auditoria-sistemas', 'Capacitação especializada para profissionais de TI, segurança e conformidade responsáveis por garantir a integridade dos sistemas e a adequação legal às exigências da Agência de Proteção de Dados de Angola (APD).', 'Auditoria técnica, conformidade com regulamentos de proteção de dados (APD Angola) e resposta imediata a incidentes de segurança.', '/images/courses/auditoria-sistemas.jpg', '110000', '55', 'advanced', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('10', '3', '9', 'Automação Digital, Inteligência Artificial e Power BI', 'automacao-digital-ia', 'Acelere a eficiência da sua organização conectando ferramentas modernas, automatizando tarefas repetitivas e construindo painéis analíticos interativos no Power BI para embasar decisões estratégicas.', 'Construção de fluxos de automação, relatórios executivos com Power BI e aplicação prática de inteligência artificial em processos de negócio.', '/images/courses/automacao-digital-ia.jpg', '90000', '50', 'intermediate', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('11', '3', '8', 'Gestão de Projectos & Metodologias Ágeis', 'gestao-projectos', 'Aprenda a liderar projetos com previsibilidade, qualidade e agilidade. Esta formação cobre tanto os conceitos fundamentais do PMI/PMBOK quanto os frameworks ágeis mais utilizados no mundo corporativo.', 'Planeamento, execução, controlo de prazos e orçamentos com Scrum, Kanban e práticas internacionais de gestão de projectos.', '/images/courses/gestao-projectos.jpg', '70000', '45', 'intermediate', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('12', '3', '8', 'Atendimento ao Cliente, CX & Excelência em Serviços', 'atendimento-cliente', 'Transforme o atendimento da sua empresa em uma vantagem competitiva inigualável. Conheça as melhores práticas de Customer Experience (CX), resolução ágil de reclamações e encantamento de clientes.', 'Comunicação assertiva, gestão de conflitos, fidelização e técnicas de excelência no relacionamento presencial e digital.', '/images/courses/atendimento-cliente.jpg', '45000', '35', 'beginner', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('13', '3', '8', 'Vendas Consultivas & Estratégias Comerciais B2B', 'vendas-b2b', 'Aprenda a estruturar um processo comercial B2B previsível e lucrativo. Aborde decisores com segurança, aplique metodologias consultivas como SPIN Selling e conclua negociações de alto valor.', 'Prospecção corporativa qualificada, negociação estratégica, técnicas de fecho e gestão de pipeline de vendas para empresas.', '/images/courses/vendas-b2b.jpg', '75000', '40', 'intermediate', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('14', '3', '8', 'Contabilidade Prática, Fiscalidade Angolana & Finanças', 'contabilidade-fiscalidade', 'Formação de alto teor técnico e prático, voltada para contabilistas, gestores financeiros e empresários que necessitam compreender a legislação tributária angolana e conduzir o fechamento das contas com total conformidade.', 'Lançamentos contabilísticos, enquadramento fiscal, obrigações AGT (IVA, IRT, Imposto Industrial) e relatórios financeiros essenciais.', '/images/courses/contabilidade-fiscalidade.jpg', '95000', '55', 'advanced', 'published', '2026-09-22T15:12:17', '2026-09-22T15:12:17', '2026-10-12 05:00:02', '2026-10-12 05:00:02');
INSERT INTO `courses` (`id`, `business_unit_id`, `category_id`, `name`, `slug`, `description`, `short_description`, `thumbnail`, `price`, `duration_hours`, `level`, `status`, `published_at`, `created_at`, `updated_at`, `deleted_at`) VALUES ('15', '3', '9', 'Curso Especializado: Engenharia Social Institucional', 'engenharia-social-institucional', 'Capacitação corporativa especializada focada no elo humano da segurança da informação. Aborda conceitos de manipulação psicológica, fraudes corporativas, engenharia social presencial e digital, governança e conformidade institucional.', 'Capacitar colaboradores e gestores a reconhecer e neutralizar ataques de engenharia social no ambiente institucional, fortalecendo a cultura de segurança organizacional.', '/images/courses/engenharia-social.jpg', '60000', '16', 'intermediate', 'published', '2026-10-12 05:00:02', '2026-10-12 05:00:02', '2026-10-12 05:00:02', NULL);
